/**
 * Catalog — the build-time snapshot of every group's tools.
 *
 * Generated by `npm run catalog` (scripts/gen-catalog.ts) from the *real*
 * registrar functions, so serve/list paths never import axoniz just to answer
 * `tools/list`. A parity test asserts the catalog always equals the live
 * registrars, so it can't silently drift.
 */

import fs from "node:fs";

import type { JsonSchemaProp, ToolMeta } from "./types.ts";

export type ToolGroup = "axoniz" | "xorvoid" | "all";

export interface CatalogTool {
  name: string;
  /** Which groups contain this tool ("axoniz" wins clashes, xorvoid shares spelling). */
  groups: Array<"axoniz" | "xorvoid">;
  description: string;
  inputSchema: {
    type: "object";
    properties: Record<string, JsonSchemaProp>;
    required: string[];
  };
  meta: ToolMeta;
}

export interface Catalog {
  /** package.json version the catalog was generated from. */
  version: string;
  tools: CatalogTool[];
}

export function catalogUrl(): URL {
  return new URL("../../catalog.json", import.meta.url);
}

export function loadCatalog(): Catalog | null {
  try {
    return JSON.parse(fs.readFileSync(catalogUrl(), "utf8")) as Catalog;
  } catch {
    return null;
  }
}

/** Filter a catalog to a group: "all" = union (deduped by name). */
export function toolsForGroup(catalog: Catalog, group: ToolGroup): CatalogTool[] {
  const list = group === "all" ? catalog.tools : catalog.tools.filter((t) => t.groups.includes(group));
  const seen = new Set<string>();
  return list.filter((t) => {
    if (seen.has(t.name)) return false;
    seen.add(t.name);
    return true;
  });
}
